window.S = (() => {
const g = ME.globe(), r = g.renderer(), gl = r.getContext(), scene = g.scene(), cam = g.camera();
const ORIG = r.render;
const q = (a, p) => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); return +s[Math.min(s.length - 1, Math.floor(p * (s.length - 1) + 0.5))].toFixed(1); };
const stats = a => ({ n: a.length, med: q(a, .5), p95: q(a, .95), max: a.length ? +Math.max(...a).toFixed(1) : null });
const env = () => ({ t: new Date().toISOString(), vw: innerWidth, vh: innerHeight, dpr: devicePixelRatio, db: [gl.drawingBufferWidth, gl.drawingBufferHeight], vis: document.visibilityState, focus: document.hasFocus() });
const polyGroups = () => { const a = []; scene.traverse(o => { if (o.__globeObjType === 'polygon') a.push(o); }); return a; };
const ids = () => { try { const ps = ME.pairState(); const o = {}; for (const k in ps) o[k] = ps[k].cells; o.forest = (window.ME && ME.state && ME.state.forest && ME.state.forest.retrieved_at) || null; return o; } catch (e) { return String(e); } };
const perLayer = () => { const o = {}; for (const p of g.polygonsData()) o[p.layer] = (o[p.layer] || 0) + 1; return o; };
const nNoRing = () => { let n = 0; const skip = new Set(); scene.traverse(o => { if (o.__globeObjType === 'ring') o.traverse(c => skip.add(c)); }); scene.traverse(o => { if (!skip.has(o)) n++; }); return n; };
const hide = (vis) => { const objs = polyGroups(); for (const o of objs) o.visible = vis; return objs.length; };
const sweep = (W = 10000, deg = 36) => new Promise(res => { g.controls().autoRotate = false; const lat = -10, lng0 = 25, alt = 2.2; let phase = 'warm', t0 = performance.now(), last = null; const frames = [], rcpu = [], calls = []; let cur = []; r.render = function (...a) { const s = performance.now(); const out = ORIG.apply(this, a); cur.push(performance.now() - s); return out; }; g.pointOfView({ lat, lng: lng0, altitude: alt }, 0); const tick = now => { if (phase === 'warm') { const el = now - t0; g.pointOfView({ lat, lng: lng0 + deg * el / 1000, altitude: alt }, 0); if (el >= 2000) { phase = 'meas'; t0 = now; last = now; cur = []; g.pointOfView({ lat, lng: lng0, altitude: alt }, 0); } requestAnimationFrame(tick); return; } const el = now - t0; frames.push(now - last); last = now; if (cur.length) { rcpu.push(cur.reduce((x, y) => x + y, 0)); calls.push(r.info.render.calls); } cur = []; if (el >= W) { r.render = ORIG; res({ frames: stats(frames.slice(1)), renderCpu: stats(rcpu), drawCalls: q(calls, .5), restored: r.render === ORIG }); return; } g.pointOfView({ lat, lng: lng0 + deg * el / 1000, altitude: alt }, 0); requestAnimationFrame(tick); }; requestAnimationFrame(tick); });
