window.P = {
  probes(pov) {
    const g = ME.globe(); g.controls().autoRotate = false; g.pointOfView(pov, 0);
    const rad = Math.PI / 180, ang = (a, b, c, d) => Math.acos(Math.min(1, Math.sin(a*rad)*Math.sin(c*rad) + Math.cos(a*rad)*Math.cos(c*rad)*Math.cos((b-d)*rad))) / rad;
    const by = {}; for (const p of g.polygonsData()) (by[p.id] = by[p.id] || []).push(p.layer);
    const cen = id => { const [r, c] = id.split('_').map(Number); return [r*4-90+2, c*4-180+2]; };
    const d = id => { const [la, ln] = cen(id); return ang(pov.lat, pov.lng, la, ln); };
    const ids = Object.keys(by).sort((a, b) => d(a) - d(b));
    const out = [];
    const ov = ids.find(i => by[i].length >= 2 && d(i) < 40); if (ov) { const [la, ln] = cen(ov); out.push({ tag: 'overlap ' + ov + ' ' + by[ov].join('+'), lat: la, lng: ln }); }
    const nb = i => { const [r, c] = i.split('_').map(Number); return r + '_' + ((c + 1) % 90); };
    const mixed = ids.find(i => by[nb(i)] && by[i].slice().sort().join() !== by[nb(i)].slice().sort().join() && d(i) < 45); if (mixed) { const [la, ln] = cen(mixed); out.push({ tag: 'edge mixed ' + mixed + '|' + nb(mixed), lat: la, lng: ln + 2 }); }
    const same = ids.find(i => by[nb(i)] && by[i].length === 1 && by[nb(i)].length === 1 && by[i][0] === by[nb(i)][0] && d(i) < 45); if (same) { const [la, ln] = cen(same); out.push({ tag: 'edge same-layer ' + by[same][0] + ' ' + same + '|' + nb(same), lat: la, lng: ln + 2 }); }
    const pts = g.pointsData().filter(q => { const c = ME.cellId(q.lat, q.lng); if (!by[c]) return false; const fl = ((q.lng + 180) % 4 + 4) % 4; return (fl < 0.2 || fl > 3.8) && ang(pov.lat, pov.lng, q.lat, q.lng) < 45; });
    if (pts[0]) out.push({ tag: 'point near cell edge in ' + ME.cellId(pts[0].lat, pts[0].lng), lat: pts[0].lat, lng: pts[0].lng });
    const limb = ids.filter(i => d(i) > 68 && d(i) < 80).sort((a, b) => Math.abs(d(a) - 75) - Math.abs(d(b) - 75))[0]; if (limb) { const [la, ln] = cen(limb); out.push({ tag: 'limb ' + limb + ' ' + by[limb].join('+') + ' @' + d(limb).toFixed(0) + 'deg', lat: la, lng: ln }); }
    let open = null; for (let k = 0; k < 400 && !open; k++) { const la = pov.lat + (k % 20 - 10) * 2, ln = pov.lng + (Math.floor(k / 20) - 10) * 2; if (Math.abs(la) < 80 && !by[ME.cellId(la, ln)] && ang(pov.lat, pov.lng, la, ln) < 30) open = { tag: 'open globe ' + ME.cellId(la, ln), lat: la, lng: ln }; } if (open) out.push(open);
    const rect = g.renderer().domElement.getBoundingClientRect();
    return out.map(o => { const s = g.getScreenCoords(o.lat, o.lng, 0.006); return { ...o, x: Math.round(rect.left + s.x), y: Math.round(rect.top + s.y) }; });
  },
  arm() { const g = ME.globe(), cv = g.renderer().domElement, insp = document.getElementById('insp'); window.__tap = { t0: null, tPaint: null };
    cv.addEventListener('pointerdown', e => { __tap.t0 = e.timeStamp; }, { once: true, capture: true });
    if (window.__mo) __mo.disconnect(); window.__mo = new MutationObserver(() => { if (__tap.t0 != null && __tap.tInsp == null) { __tap.tInsp = performance.now(); requestAnimationFrame(() => requestAnimationFrame(() => { __tap.tPaint = performance.now(); })); } }); __mo.observe(insp, { subtree: true, childList: true, characterData: true, attributes: true }); },
  hover() { const t = document.querySelector('.float-tooltip-kap'); return t && getComputedStyle(t).display !== 'none' && t.textContent ? t.textContent.replace(/\s+/g, ' ').slice(0, 34) : null; },
  async after() { await new Promise(f => setTimeout(f, 900)); const i = document.getElementById('insp'), h = document.getElementById('insp-h'); const v = i.classList.contains('show') && h ? h.textContent.replace(/\s+/g, ' ').slice(0, 34) : null; const tp = __tap.t0 != null && __tap.tPaint != null ? +(__tap.tPaint - __tap.t0).toFixed(0) : null; const x = document.getElementById('insp-x'); if (x && i.classList.contains('show')) x.click(); return { insp: v, tap: tp }; }
};
